def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    if opp[-1] == 'D':
        return 'D'

    retaliated = False
    for i in range(n):
        if me[i] == 'D' and opp[i] == 'C':
            if i + 1 < n and opp[i + 1] == 'D':
                retaliated = True
                break
            if i + 2 < n and opp[i + 2] == 'D':
                retaliated = True
                break

    if retaliated:
        return 'C'

    last_probe = -1
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'C':
            last_probe = i
            break

    probe_count = 0
    for i in range(n):
        if me[i] == 'D' and opp[i] == 'C':
            probe_count += 1

    if probe_count < 3:
        interval = 3
    elif probe_count < 6:
        interval = 2
    else:
        interval = 1

    if n - last_probe >= interval:
        return 'D'
    else:
        return 'C'
